mapper.select:
SELECT 
FROM sms_outbox_event
WHERE status = 0 AND next_execute_time <= #{now}
ORDER BY next_execute_time ASC, create_time ASC
LIMIT #{limit}

SELECT 
FROM sms_outbox_event
WHERE status = 1 AND lease_expire_time < #{before}
ORDER BY lease_expire_time ASC
LIMIT #{limit}

mapper.update:
UPDATE sms_outbox_event
SET status = 2, lease_owner = NULL, lease_expire_time = NULL, update_time = #{updateTime}
WHERE id = #{id} AND status = 1 AND lease_owner = #{leaseOwner}
